def register_commands(app):
    @app.cli.command('create-admin')
    @click.option('--email', prompt='Email')
    @click.option('--name', prompt='Имя')
    @click.password_option(confirmation_prompt=True)
    def create_admin(email, name, password):
        migrate()
        if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', email) or not 2 <= len(name) <= 80 or not 10 <= len(password) <= 128:
            raise click.ClickException('Проверьте email, имя и пароль (10–128 символов).')
        if one('SELECT id FROM users WHERE email=?', (email,)):
            raise click.ClickException('Email уже используется. Команда не повышает права существующих аккаунтов.')
        db().execute("INSERT INTO users(email,name,password,role) VALUES (?,?,?,'admin')", (email.lower(), name, generate_password_hash(password)))
        db().commit()
        click.echo('Администратор создан.')

    @app.cli.command('seed-demo')
    def seed_demo():
        migrate()
        if one('SELECT id FROM courses LIMIT 1'):
            raise click.ClickException('Демонстрация создаётся только в базе без курсов, чтобы не затронуть ваши данные.')
        for idx, (title, category, level, short, outcomes, modules) in enumerate(COURSES):
            db().execute('INSERT OR IGNORE INTO categories(name) VALUES (?)', (category,))
            cat = one('SELECT id FROM categories WHERE name=?', (category,))['id']
            cid = db().execute("INSERT INTO courses(title,summary,description,outcomes,prerequisites,category_id,level,status,cover) VALUES (?,?,?,?,?,?,?,'published',?)",
                               (title, short, short + ' Курс сочетает короткие объяснения, практические задания и проверяемые результаты. Проходите материалы в удобном темпе и возвращайтесь к заметкам в любой момент.', outcomes,
                                'Уверенное владение компьютером. Для среднего и продвинутого уровня — базовый опыт разработки.', cat, level, f'/static/covers/{idx+1}.svg')).lastrowid
            for mp, (mtitle, content) in enumerate(modules):
                mid = db().execute('INSERT INTO modules(course_id,title,position) VALUES (?,?,?)', (cid, mtitle, mp)).lastrowid
                for lp, (ltitle, body) in enumerate(content):
                    lid = db().execute('INSERT INTO lessons(module_id,title,content,minutes,position) VALUES (?,?,?,?,?)', (mid, ltitle, body, 20 + lp * 5, lp)).lastrowid
                    if idx == 0 and 'проверка' in ltitle.lower() or idx == 0 and 'Проверяем' in ltitle:
                        qid = db().execute('INSERT INTO quizzes(lesson_id,pass_score) VALUES (?,70)', (lid,)).lastrowid
                        for qt, opts, correct, explanation in [
                            ('Что возвращает sum([2, 3, 5])?', ['10', '235', '[2, 3, 5]'], [0], 'sum складывает числовые элементы коллекции: 2 + 3 + 5 = 10.'),
                            ('Выберите изменяемые коллекции Python.', ['Список list', 'Словарь dict', 'Кортеж tuple'], [0, 1], 'Списки и словари изменяемы. Кортеж нельзя изменить после создания.'),
                            ('Какой подход точнее для денежных расчётов?', ['Случайное округление', 'Decimal или целые копейки', 'Строковая конкатенация'], [1], 'Decimal и целые копейки позволяют избежать погрешностей двоичной арифметики.')]:
                            db().execute('INSERT INTO questions(quiz_id,text,options,correct,explanation) VALUES (?,?,?,?,?)', (qid, qt, json.dumps(opts, ensure_ascii=False), json.dumps(correct), explanation))
        demo_password = secrets.token_urlsafe(14)
        for index, name in enumerate(['Анна Смирнова', 'Михаил Волков', 'Елена Кузнецова']):
            email = f'demo{index+1}@example.test'
            uid = db().execute('INSERT INTO users(email,name,password) VALUES (?,?,?)', (email, name, generate_password_hash(demo_password))).lastrowid
            for cid in range(1, 3 + index):
                eid = db().execute('INSERT INTO enrollments(user_id,course_id) VALUES (?,?)', (uid, cid)).lastrowid
                event(uid, cid, 'Запись на демонстрационный курс', True)
                e = one('SELECT * FROM enrollments WHERE id=?', (eid,))
                for l in lessons(cid)[:(1 if index == 0 else 2 if index == 1 else 100)]:
                    q = one('SELECT id FROM quizzes WHERE lesson_id=?', (l['id'],))
                    if q:
                        questions = db().execute('SELECT id,correct FROM questions WHERE quiz_id=?', (q['id'],)).fetchall()
                        answers = {str(x['id']): json.loads(x['correct']) for x in questions}
                        db().execute("INSERT INTO attempts(user_id,quiz_id,score,passed,answers,feedback) VALUES (?,?,100,1,?,'[]')", (uid, q['id'], json.dumps(answers)))
                    complete(l, e)
                    e = one('SELECT * FROM enrollments WHERE id=?', (eid,))
                if e['completed_at']:
                    db().execute('INSERT INTO reviews(user_id,course_id,rating,text) VALUES (?,?,5,?)', (uid, cid, 'Понятные объяснения и полезная практика. Особенно понравились задания, которые можно применить в собственном проекте.'))
        db().commit()
        click.echo('Созданы 6 курсов и 3 пользователя: demo1@example.test, demo2@example.test, demo3@example.test')
        click.echo('Временный пароль демонстрационных пользователей: ' + demo_password)
        click.echo('Администратор не создаётся автоматически. Используйте create-admin.')

